<?php
declare(strict_types=1); namespace Theobroma\OneC\Admin;
use Theobroma\OneC\Settings\Settings;
final class SettingsPage {public function register():void{add_action('admin_menu',[$this,'menu']);add_action('admin_init',[$this,'settings']);}public function menu():void{add_submenu_page('woocommerce','Интеграция с 1С','Интеграция с 1С','manage_woocommerce','theobroma-1c',[$this,'render']);}public function settings():void{register_setting('theobroma_1c',Settings::OPTION,['sanitize_callback'=>[$this,'sanitize']]);}public function sanitize(array$input):array{$old=(new Settings())->get();$password=trim((string)($input['password']??''));return['enabled'=>!empty($input['enabled']),'username'=>sanitize_user((string)($input['username']??''),true),'password_hash'=>$password!==''?wp_hash_password($password):$old['password_hash'],'batch_size'=>min(100,max(1,(int)($input['batch_size']??50)))];}public function render():void{if(!current_user_can('manage_woocommerce'))return;$s=(new Settings())->get();echo'<div class="wrap"><h1>Интеграция с 1С</h1><p>URL: <code>'.esc_html(home_url('/theobroma-1c/exchange')).'</code></p><form method="post" action="options.php">';settings_fields('theobroma_1c');echo'<table class="form-table"><tr><th>Включить</th><td><input type="checkbox" name="'.Settings::OPTION.'[enabled]" value="1" '.checked($s['enabled'],true,false).'></td></tr><tr><th>Логин</th><td><input name="'.Settings::OPTION.'[username]" value="'.esc_attr($s['username']).'"></td></tr><tr><th>Новый пароль</th><td><input type="password" autocomplete="new-password" name="'.Settings::OPTION.'[password]"></td></tr><tr><th>Заказов в пакете</th><td><input type="number" min="1" max="100" name="'.Settings::OPTION.'[batch_size]" value="'.$s['batch_size'].'"></td></tr></table>';submit_button();echo'</form>';$this->import();echo'</div>';}private function import():void{echo'<hr><h2>Импорт идентификаторов Ozon</h2><form method="post" enctype="multipart/form-data" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="theobroma_1c_ozon_preview">';wp_nonce_field('theobroma_1c_ozon_preview');echo'<input type="file" name="ozon_file" accept=".csv,.tsv,text/csv,text/tab-separated-values" required> ';submit_button('Предварительный просмотр','secondary','submit',false);echo'</form>';$preview=OzonImportPage::previewData();if(!$preview)return;$products=wc_get_products(['status'=>'publish','limit'=>-1]);echo'<form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="theobroma_1c_ozon_apply">';wp_nonce_field('theobroma_1c_ozon_apply');echo'<table class="widefat"><thead><tr><th>Строка</th><th>Статус</th><th>Товар</th></tr></thead><tbody>';foreach($preview as$i=>$item){$row=$item['row'];$status=(string)$item['status'];echo'<tr><td>'.esc_html($row->clientArticle.' — '.$row->name).'</td><td>'.esc_html($status).'</td><td>';if((int)$item['product_id']>0)echo'#'.(int)$item['product_id'];else{echo'<select name="product_id['.$i.']"><option value="">Не сопоставлять</option>';foreach($products as$p)echo'<option value="'.$p->get_id().'">'.esc_html($p->get_name().' ['.$p->get_sku().']').'</option>';echo'</select>';}echo'</td></tr>';}echo'</tbody></table>';submit_button('Применить однозначные и выбранные сопоставления');echo'</form>';}}
